<script>(function(){var f=document.getElementById('debtCollectionForm');if(!f)return;var d=document.getElementById('debtDescription'),c=document.getElementById('debtDescriptionCount');function n(){return d.value.trim()?d.value.trim().split(/\s+/).length:0}function u(){var x=n();c.textContent=x+'/200 từ';c.style.color=x>200?'#b42318':'#667085'}d.addEventListener('input',u);f.addEventListener('submit',function(e){if(n()>200){e.preventDefault();alert('Diễn giải tối đa 200 từ.')}});u()})();</script>
